import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdtempSync, rmSync, symlinkSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import { dirname, join, relative, sep } from 'node:path';

import { afterEach, describe, expect, it } from 'vitest';

/**
 * The unit suite must still COLLECT when the project has no pnpm-workspace.yaml of its own.
 *
 * That is the normal layout of every API generated by `lt fullstack init` / `add-api`: the CLI
 * hoists this settings-only file into the monorepo root and deletes it here. A spec that reads the
 * file while vitest collects tests fails its whole file there, even inside `describe.skipIf(...)`,
 * because vitest still executes a skipped describe's body to collect it.
 * audit-suppression-scope.spec.ts did exactly that: the API unit tests of every new fullstack
 * project were red, while this repository, which has the file, stayed green.
 *
 * `vitest list` collects without running a single test, so it reproduces that layout in about two
 * seconds: copy the project without the file, list, require a clean exit. It does not cover a test
 * BODY that needs the file. Such a test needs its own skip, and the generated project's real run is
 * what catches a missing one.
 */
const ROOT = join(__dirname, '../..');
const OWN_WORKSPACE = existsSync(join(ROOT, 'pnpm-workspace.yaml'));

/** Top-level entries the copy leaves out: the file under test, and bulk the suite never reads. */
const LEFT_OUT = new Set(['.git', 'coverage', 'dist', 'node_modules', 'pnpm-workspace.yaml', 'uploads']);

describe('unit suite without an own pnpm-workspace.yaml (monorepo layout)', () => {
  let dir: string | undefined;

  afterEach(() => {
    if (dir) {
      rmSync(dir, { force: true, recursive: true });
      dir = undefined;
    }
  });

  // Skipped where the file is already absent: in a generated monorepo project the real unit run
  // IS this check, and its hoisted node_modules would not fit the copy below anyway.
  it.skipIf(!OWN_WORKSPACE)(
    'collects every unit spec',
    () => {
      dir = mkdtempSync(join(tmpdir(), 'hoisted-layout-'));
      cpSync(ROOT, dir, {
        filter: (src) => !LEFT_OUT.has(relative(ROOT, src).split(sep)[0]),
        recursive: true,
      });
      // `junction` makes the link work on Windows without admin rights; POSIX ignores the type.
      symlinkSync(join(ROOT, 'node_modules'), join(dir, 'node_modules'), 'junction');

      const vitestCli = join(
        dirname(createRequire(join(ROOT, 'package.json')).resolve('vitest/package.json')),
        'vitest.mjs',
      );
      // The child must not believe it is a worker of THIS run.
      const env = Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.startsWith('VITEST')));
      const result = spawnSync(process.execPath, [vitestCli, 'list', '--config', 'vitest.config.ts'], {
        cwd: dir,
        encoding: 'utf8',
        env,
      });

      expect(result.status, `${result.stdout}\n${result.stderr}`.slice(-3000)).toBe(0);
      // Not vacuous: the copy really collected the suite. Skipped tests are not listed, so this
      // names a spec that runs in every layout and on every platform.
      expect(result.stdout).toContain('db-lifecycle-guard.spec.ts > ');
    },
    60_000,
  );
});
